import "./index.css";
import { Composition } from "remotion";
import { SivoExplainer } from "./sivo/SivoExplainer";
import { SivoListicle } from "./sivo/SivoListicle";
import { SivoNews } from "./sivo/SivoNews";
import { NewsStyle } from "./sivo/NewsStyle";
import { XStyle } from "./sivo/XStyle";
import { sivoManifestSchema, type SivoManifest } from "./sivo/types";

// Default props are a placeholder so the compositions register. Real renders
// always pass a full manifest via inputProps (see scripts/render.mjs).
// The default scene points at a 3s silent WAV generated by build_props.py.
const defaultProps: SivoManifest = {
  version: "sivo-remotion-poc-1",
  style: "fireship",
  template: "explainer",
  brand: "",
  memeOn: false,
  voice: "default",
  fps: 30,
  warnings: [],
  scenes: [
    {
      id: "scene1_hook",
      role: "hook",
      text: "Default placeholder scene.",
      headline: "PLACEHOLDER",
      audioPath: "audio/_default/silence.wav",
      durationInFrames: 90,
    },
  ],
};

function durationFromProps(props: SivoManifest): number {
  return props.scenes.reduce(
    (acc, s, i) =>
      acc + s.durationInFrames + (i === props.scenes.length - 1 ? 10 : 3),
    0
  );
}

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="SivoExplainer"
        component={SivoExplainer}
        durationInFrames={93}
        fps={30}
        width={1080}
        height={1920}
        schema={sivoManifestSchema}
        defaultProps={defaultProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: durationFromProps(props),
        })}
      />
      <Composition
        id="SivoListicle"
        component={SivoListicle}
        durationInFrames={93}
        fps={30}
        width={1080}
        height={1920}
        schema={sivoManifestSchema}
        defaultProps={defaultProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: durationFromProps(props),
        })}
      />
      <Composition
        id="SivoNews"
        component={SivoNews}
        durationInFrames={93}
        fps={30}
        width={1080}
        height={1920}
        schema={sivoManifestSchema}
        defaultProps={defaultProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: durationFromProps(props),
        })}
      />
      <Composition
        id="NewsStyle"
        component={NewsStyle}
        durationInFrames={93}
        fps={30}
        width={1080}
        height={1920}
        schema={sivoManifestSchema}
        defaultProps={defaultProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: durationFromProps(props),
        })}
      />
      <Composition
        id="XStyle"
        component={XStyle}
        durationInFrames={93}
        fps={30}
        width={1080}
        height={1920}
        schema={sivoManifestSchema}
        defaultProps={defaultProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: durationFromProps(props),
        })}
      />
    </>
  );
};
